692	// ────────────────────────────────────────────────────────────────────────────
693	//  BACKWARD for one sample (CTA-cooperative). Assumes dec_forward_sample has run
694	//  for THIS sample (so layer_in/final_in/fn caches/logits are populated and
695	//  reflect this sample). Accumulates every weight grad into the CTA's partial
696	//  buffer `g` (DecGrad over gw_cta). Uses extra smem scratch passed via sm.
697	//
698	//  Transcribed from tests/hw/decoder_oracle.py::decoder_backward.
699	// ────────────────────────────────────────────────────────────────────────────
700	__device__ inline void dec_backward_sample(const DecWeights& w, const DecGrad& g,
701	                                     const int* tokens_s, int target, int B,
702	                                     DecSampleSmem* sm) {
703	    // ── CE backward: dlogits = (softmax - onehot)/B. (logits cached in fwd.) ──
704	    float lmax = -CUDART_INF_F;
705	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
706	        lmax = fmaxf(lmax, sm->logits[o]);
707	    lmax = dec_block_max(lmax, sm->red);
708	    float es = 0.0f;
709	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x)
710	        es += __expf(sm->logits[o] - lmax);
711	    es = dec_block_sum(es, sm->red);
712	    float inv_es = 1.0f / es;
713	    // overwrite logits[] with dlogits in place.
714	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
715	        float sm_o = __expf(sm->logits[o] - lmax) * inv_es;
716	        float dl = (sm_o - ((o == target) ? 1.0f : 0.0f)) / (float)B;
717	        sm->logits[o] = dl;
718	    }
719	    __syncthreads();
720	    // ── head (out): logits = hn @ out_w^T + out_b. hn was stashed in x1[0]
721	    //    during fwd, but x1 has since been reused — recompute hn from the
722	    //    cached final-norm: hn[j] = fn_xhat[last][j]*norm_w[j] + norm_b[j]. ──
723	    // dW_out[o,:] += dlogits[o] * hn ; db_out[o] += dlogits[o].
724	    // dhn[j] = sum_o dlogits[o] * out_w[o,j].
725	    for (int o = threadIdx.x; o < dec::kVocab; o += blockDim.x) {
726	        float dl = sm->logits[o];
727	        g.out_b[o] += dl;
728	        float* gwrow = g.out_w + (int64_t)o * dec::kD;
729	        const float* xh = &sm->fn_xhat[dec::kSeq - 1][0];
730	        #pragma unroll 4
731	        for (int j = 0; j < dec::kD; ++j) {
732	            float hn_j = xh[j] * w.norm_w[j] + w.norm_b[j];
733	            gwrow[j] += dl * hn_j;
734	        }
735	    }
736	    __syncthreads();
737	    // dhn[j] (feature-parallel) into dh row 0 scratch.
738	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
739	        float acc = 0.0f;
740	        for (int o = 0; o < dec::kVocab; ++o)
741	            acc += sm->logits[o] * w.out_w[(int64_t)o * dec::kD + j];
742	        sm->dh[0][j] = acc;   // dhn
743	    }
744	    __syncthreads();
745	    // ── final norm backward: dy=dhn (row last), xhat=fn_xhat[last], inv=fn_inv.
746	    //    Produces dh_last into dh[last]; accumulate dnorm_w/dnorm_b. Use a single
747	    //    "position" (last). Build a 1-row dy view: reuse sm->ctx row last = dhn. ─
748	    for (int j = threadIdx.x; j < dec::kD; j += blockDim.x)
749	        sm->ctx[dec::kSeq - 1][j] = sm->dh[0][j];   // dy at last position
