71	// ─────────────────────────────────────────────────────────────────────────
72	//  Stage spec: contiguous layer split. NumStages must divide kLayers (the
73	//  2-layer race decoder ⇒ NumStages=2 ⇒ 1 layer/stage; ladder depths divide
74	//  evenly by construction — the host plan asserts before instantiating).
75	// ─────────────────────────────────────────────────────────────────────────
76	template <int Stage, int NumStages>
77	struct PPStageSpec {
78	    static_assert(NumStages >= 1 && NumStages <= dec::kLayers,
79	                  "PP: NumStages must be in [1, kLayers]");
80	    static_assert(dec::kLayers % NumStages == 0,
81	                  "PP: contiguous even split requires NumStages | kLayers");
82	    static_assert(Stage >= 0 && Stage < NumStages, "PP: Stage out of range");
83	
84	    static constexpr int kLayersPerStage = dec::kLayers / NumStages;
85	    static constexpr int kLlo = Stage * kLayersPerStage;
86	    static constexpr int kLhi = kLlo + kLayersPerStage;
87	    static constexpr bool kIsFirst = (Stage == 0);
88	    static constexpr bool kIsLast  = (Stage == NumStages - 1);
89	
90	    // dW spec ownership (dectc_build_dw_specs order: 4 specs/layer + head=8).
91	    static constexpr int kSpecLo = 4 * kLlo;
92	    static constexpr int kSpecHi = 4 * kLhi;
93	    __device__ __forceinline__ static bool owns_spec(int s) {
94	        return (s >= kSpecLo && s < kSpecHi) || (kIsLast && s == 8);
95	    }
96	    // LN-vec slot ownership (dectc::kLnVecTensorIdx order: 4 slots/layer + 8,9).
97	    __device__ __forceinline__ static bool owns_lnvec(int v) {
98	        return (v >= 4 * kLlo && v < 4 * kLhi) || (kIsLast && v >= 8);
99	    }
100	    // Flat tensor ownership (dec_layout order) — host-side mirror lives in
101	    // grokking_optimizers/parallel/pipeline.py::stage_tensor_ownership (the two
102	    // are cross-checked by tests/test_pipeline_schedule.py via this header's
103	    // constants printed by the binding).
104	    __host__ __device__ __forceinline__ static bool owns_tensor(int t) {
105	        if (t >= 2 + 12 * kLlo && t < 2 + 12 * kLhi) return true;   // layer block
106	        if (kIsFirst && (t == 0 || t == 1)) return true;            // tok, pos
107	        if (kIsLast && t >= 26 && t <= 29) return true;             // norm + head
108	        return false;
109	    }
110	};
111	
112	// ─────────────────────────────────────────────────────────────────────────
113	//  FWD-ONLY stage kernel (single phase — no grid barriers, no grad writes).
114	//  Writes this stage's acts X-regions; the boundary X_in[kLhi] is the handoff.
115	//  Last stage included for completeness (1F1B never schedules it: its fwd+bwd
116	//  run fused in pp_decoder_stage_bwd_tc).
117	// ─────────────────────────────────────────────────────────────────────────
118	template <int Stage, int NumStages>
119	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
120	pp_decoder_stage_fwd_tc(PersistentContext ctx,
121	                        const float* __restrict__ params,
122	                        DecoderTokenCtx tok) {
123	    using S = PPStageSpec<Stage, NumStages>;
124	    __shared__ DecTcSmem sm;
125	    const int cta = blockIdx.x;
126	    const int nCTA = (int)ctx.n_ctas;
127	    const int B = tok.B;
128	    const int T = B * dec::kSeq;
129	
130	    // Workspace partition — IDENTICAL carve to the fused TC kernel (shared
131	    // workspace across the stage launches of one step ⇒ identical offsets).
132	    float* ws = tok.workspace;
133	    const int64_t acts_f = dec_tc_acts_floats(T, B);
134	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
135	    float* scratch_base = ws + acts_f;
136	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
137	
138	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
139	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
140	    DecWeights w = dec_bind(const_cast<float*>(params));
141	
142	    const int nrows_tile = dectc::kTileM;
143	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
144	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
145	        const int g0 = ti * nrows_tile;
146	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
147	        (void)dectc::dectc_forward_tile<S::kLlo, S::kLhi>(
148	            w, g0, nrows, acts, sc, tok.tokens, tok.targets, sm.sA, sm.sB, sm.red);
149	        __syncthreads();
150	    }
151	}
152	
153	// ─────────────────────────────────────────────────────────────────────────
154	//  FWD-RECOMPUTE + BWD + OWNED-GRAD-ASSEMBLY stage kernel. Mirrors the fused
155	//  TC kernel's P0→B0→P1→B1→P2 with the layer-range tiles and owned-tensor
156	//  filters; ends at the B2-equivalent (owned grad assembled in `grad`).
157	//
158	//  dh_in : fp32 [T,d] boundary adjoint from the DOWNSTREAM stage
159	//          (required unless last stage — last stage starts from CE).
160	//  dh_out: fp32 [T,d] boundary adjoint for the UPSTREAM stage
161	//          (required unless first stage — first stage writes dh0/embeds).
162	//  Preconditions (loopback shares one workspace; real PP copies regions in):
163	//    * this stage's input acts X_in[kLlo] are populated (upstream fwd handoff);
164	//    * for the last stage, nothing else; for others, dh_in is populated.
165	// ─────────────────────────────────────────────────────────────────────────
166	template <int Stage, int NumStages>
167	__global__ void __launch_bounds__(SG_TC_MEGA_BLOCK)
168	pp_decoder_stage_bwd_tc(PersistentContext ctx,
169	                        const float* __restrict__ params,
170	                        DecoderTokenCtx tok,
171	                        float* __restrict__ grad,
172	                        const float* __restrict__ dh_in,
173	                        float* __restrict__ dh_out) {
174	    using S = PPStageSpec<Stage, NumStages>;
175	    __shared__ DecTcSmem sm;
176	    GridBarrier bar = ctx.barrier();
177	    const int cta = blockIdx.x;
178	    const int nCTA = (int)ctx.n_ctas;
179	    const int B = tok.B;
180	    const int T = B * dec::kSeq;
181	
182	    // Workspace partition — byte-identical carve to fused_decoder_megakernel_tc
183	    // (same helpers, same order) so the loopback can share one workspace with
184	    // identical region addresses (dw_part slot bases included).
185	    float* ws = tok.workspace;
186	    const int64_t acts_f = dec_tc_acts_floats(T, B);
187	    __nv_bfloat16* acts_base = reinterpret_cast<__nv_bfloat16*>(ws);
188	    float* scratch_base = ws + acts_f;
189	    const int64_t scratch_per = dectc::dec_tile_scratch_total_f32();
190	    float* lnvec_base = scratch_base + (int64_t)nCTA * scratch_per;
191	    float* loss_part  = lnvec_base + (int64_t)nCTA * dectc::kLnVecElems;
192	    float* loss_out   = loss_part + nCTA;
193	    float* dw_part    = loss_out + 1;
194	    const int kDwG    = dectc::kDecDwSplitK;
195	    float* embed_ws_base = dw_part + dec_tc_dw_part_floats()
196	                         + dec_tc_staged_opt_floats(nCTA);
197	    if (((uintptr_t)embed_ws_base & 0x7) != 0) embed_ws_base += 1;  // 8-byte align
198	    int* embed_row_start = reinterpret_cast<int*>(embed_ws_base);   // [V+1]
199	    int* embed_perm      = embed_row_start + (dec::kVocab + 1);     // [T]
200	
201	    dectc::DecActs acts = dectc::dec_acts_bind(acts_base, T, B);
202	    dectc::DecTileScratch sc = dectc::dec_tile_scratch_bind(scratch_base + (int64_t)cta * scratch_per);
203	    float* my_lnvec = lnvec_base + (int64_t)cta * dectc::kLnVecElems;
204	    DecWeights w = dec_bind(const_cast<float*>(params));
205	
206	    // ── P0: zero this CTA's LN-vec partials + loss slot (mirrors fused P0). ──
207	    for (int i = threadIdx.x; i < dectc::kLnVecElems; i += blockDim.x) my_lnvec[i] = 0.0f;
208	    if (threadIdx.x == 0) loss_part[cta] = 0.0f;
209	    bar.sync();   // B0
210	
211	    // Embedding token lists: ONLY the stage that owns the embeddings consumes
212	    // them; built once on cta 0 in the P1 window (fused-kernel pattern).
213	    if (S::kIsFirst && cta == 0)
214	        dectc::dectc_embed_build_lists(tok.tokens, T, embed_row_start, embed_perm);
215	
216	    // ── P1: fwd<Llo,Lhi> RECOMPUTE (repopulates this CTA's tile scratch +
217	    //    this stage's acts — bit-identical to the fwd launch's values) then
218	    //    bwd<Llo,Lhi> with the boundary adjoints. ──
219	    const int nrows_tile = dectc::kTileM;
220	    const int n_tiles = (T + nrows_tile - 1) / nrows_tile;
221	    float nll_acc = 0.0f;
222	    for (int ti = cta; ti < n_tiles; ti += nCTA) {
223	        const int g0 = ti * nrows_tile;
224	        const int nrows = (T - g0) < nrows_tile ? (T - g0) : nrows_tile;
225	        float nll = dectc::dectc_forward_tile<S::kLlo, S::kLhi>(
226	            w, g0, nrows, acts, sc, tok.tokens, tok.targets, sm.sA, sm.sB, sm.red);
227	        dectc::dectc_backward_tile<S::kLlo, S::kLhi>(
228	            w, g0, nrows, B, acts, sc, tok.targets, my_lnvec, sc.work2,
229	            sm.sA, sm.sB, sm.red, dh_in, dh_out);
230	        if (threadIdx.x == 0) nll_acc += nll;
231	        __syncthreads();
232	    }
233	    if (threadIdx.x == 0) loss_part[cta] = nll_acc;
234	    bar.sync();   // B1: this stage's acts (X + dY) + LN-vec partials complete
235	
236	    // ── P2: assemble the OWNED grads. Same global work-item space + slot bases
237	    //    as the fused kernel (so the loopback composition is offset-identical);
238	    //    non-owned items are SKIPPED (the owning stage writes them). ──
239	    if (threadIdx.x == 0) dectc::dectc_build_dw_specs(acts, B, T, sm.spec);
240	    __syncthreads();
241	    dectc::DecDwSpec* spec = sm.spec;
242	    const int n_dw = dectc::dectc_dw_total_tiles<SG_TUNED_TILE_N>(spec);
243	
244	    if (kDwG > 1) {
245	        // Split-K partials for OWNED tiles only (identical (gt,kc) slot bases).
246	        for (int item = cta; item < n_dw * kDwG; item += nCTA) {
247	            const int gt = item / kDwG, kc = item % kDwG;
248	            int s, mg, nt;
249	            dectc::dectc_dw_decode<SG_TUNED_TILE_N>(spec, gt, s, mg, nt);
250	            if (!S::owns_spec(s)) continue;
251	            dectc::dectc_dw_run_tile_splitk<SG_TUNED_TILE_N>(spec, gt, kc, kDwG, dw_part, sm.sA, sm.sB);
252	        }
253	        bar.sync();   // all owned (gt,kc) partials complete
254	        // Deterministic ascending-kc reduce, filtered to owned tiles.
255	        for (int gt = cta; gt < n_dw; gt += nCTA) {
256	            int s, m_group, n_tile;
257	            dectc::dectc_dw_decode<SG_TUNED_TILE_N>(spec, gt, s, m_group, n_tile);
258	            if (!S::owns_spec(s)) continue;
259	            const dectc::DecDwSpec& sp = spec[s];
260	            const int mbase = m_group * dectc::kDecDwIL * 64;
261	            const int n0 = n_tile * SG_TUNED_TILE_N;
262	            const int n_real = (sp.Kin - n0) < SG_TUNED_TILE_N ? (sp.Kin - n0) : SG_TUNED_TILE_N;
263	            const int grp_rows = dectc::kDecDwIL * 64;
264	            const int Nrow = (sp.Nout - mbase) < grp_rows ? (sp.Nout - mbase) : grp_rows;
265	            const int64_t base = (int64_t)gt * kDwG * dectc::kDecDwTileFloats;
266	            for (int idx = threadIdx.x; idx < Nrow * n_real; idx += blockDim.x) {
267	                const int row = idx / n_real, col = idx % n_real;
268	                float accv = 0.0f;
269	                for (int kc = 0; kc < kDwG; ++kc)
270	                    accv += dw_part[base + (int64_t)kc * dectc::kDecDwTileFloats
271	                                    + (int64_t)row * SG_TUNED_TILE_N + col];
272	                grad[sp.grad_off + (int64_t)(mbase + row) * sp.Kin + n0 + col] = accv;
273	            }
274	        }
275	    } else {
276	        for (int gt = cta; gt < n_dw; gt += nCTA) {
277	            int s, mg, nt;
278	            dectc::dectc_dw_decode<SG_TUNED_TILE_N>(spec, gt, s, mg, nt);
279	            if (!S::owns_spec(s)) continue;
280	            dectc::dectc_dw_run_tile<SG_TUNED_TILE_N>(spec, gt, grad, sm.sA, sm.sB);
281	        }
282	    }
283	
284	    // Owned biases (single-owner grid-stride column-sum over the GLOBAL bias
285	    // index space — same owner map as fused; non-owned outputs skipped).
286	    {
287	        int pre[10];
288	        pre[0] = 0;
289	        #pragma unroll
290	        for (int s = 0; s < 9; ++s) pre[s + 1] = pre[s] + spec[s].Nout;
291	        const int total_b = pre[9];
292	        const int stride = nCTA * blockDim.x;
293	        for (int go = cta * blockDim.x + threadIdx.x; go < total_b; go += stride) {
294	            int s = 0;
295	            #pragma unroll
296	            for (int t = 0; t < 9; ++t) if (go >= pre[t + 1]) s = t + 1;
297	            if (!S::owns_spec(s)) continue;
298	            const dectc::DecDwSpec& sp = spec[s];
299	            const int o = go - pre[s];
300	            float accv = 0.0f;
301	            for (int k = 0; k < sp.K; ++k)
302	                accv += __bfloat162float(sp.dY_bias[(int64_t)k * sp.Nout + o]);
303	            grad[sp.bias_off + o] = accv;
304	        }
305	    }
306	
307	    // Embedding grads (tok/pos) — first stage only (it owns dh0 + the lists).
308	    if (S::kIsFirst)
309	        dectc::dectc_embed_owner_scan(acts, embed_row_start, embed_perm, T, grad, cta, nCTA);
310	
311	    // Owned LN-vec slots (ascending-CTA reduce, fused pattern, filtered).
312	    for (int v = cta; v < dectc::kNumLnVec; v += nCTA) {
313	        if (!S::owns_lnvec(v)) continue;
314	        const int goff = dectc::kLnVecTensorIdx[v];
315	        const int64_t gbase = kDecOffsets[goff];
316	        for (int j = threadIdx.x; j < dec::kD; j += blockDim.x) {
317	            float accv = 0.0f;
318	            for (int c = 0; c < nCTA; ++c)
319	                accv += lnvec_base[(int64_t)c * dectc::kLnVecElems + (int64_t)v * dec::kD + j];
320	            grad[gbase + j] = accv;
321	        }
322	    }
323	
324	    // Loss reduce (fp64, CTA 0) — last stage only (it ran CE).
325	    if (S::kIsLast && cta == 0 && threadIdx.x == 0) {
326	        double s = 0.0;
327	        for (int c = 0; c < nCTA; ++c) s += (double)loss_part[c];
328	        *tok.loss_out = (float)(s / (double)B);
329	    }
330	    // B2-equivalent: owned grad assembled; kernel exits (the optimizer is the
331	    // separate sharded-opt kernel per the design §2.2 cut — already gated).
332	}
