334	// ─────────────────────────────────────────────────────────────────────────
335	//  Launchers — mirror launch_fused_decoder_megakernel_tc's discipline exactly:
336	//  one CTA/SM (ncta_cap-able), occupancy>=1 refuse-or-hang guard, B%16 gate,
337	//  barrier/queue slots zeroed before launch.
338	// ─────────────────────────────────────────────────────────────────────────
339	template <int Stage, int NumStages>
340	cudaError_t launch_pp_decoder_stage_fwd_tc(
341	        PersistentContext ctx, const float* params, DecoderTokenCtx tok,
342	        cudaStream_t stream, int ncta_cap = 0) {
343	    int dev = 0;
344	    cudaError_t err = cudaGetDevice(&dev);
345	    if (err != cudaSuccess) return err;
346	    int n_sms = 0;
347	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
348	    if (err != cudaSuccess) return err;
349	    int occ = 0;
350	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
351	        &occ, (const void*)&pp_decoder_stage_fwd_tc<Stage, NumStages>,
352	        SG_TC_MEGA_BLOCK, 0);
353	    if (err != cudaSuccess) return err;
354	    if (occ < 1) return cudaErrorLaunchOutOfResources;
355	    unsigned launch_ctas = (unsigned)n_sms;
356	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
357	    ctx.n_ctas = launch_ctas;
358	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
359	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
360	    pp_decoder_stage_fwd_tc<Stage, NumStages><<<grid, block, 0, stream>>>(ctx, params, tok);
361	    return cudaGetLastError();
362	}
363	
364	template <int Stage, int NumStages>
365	cudaError_t launch_pp_decoder_stage_bwd_tc(
366	        PersistentContext ctx, const float* params, DecoderTokenCtx tok,
367	        float* grad, const float* dh_in, float* dh_out,
368	        cudaStream_t stream, int ncta_cap = 0) {
369	    using S = PPStageSpec<Stage, NumStages>;
370	    // Loud preconditions: a non-last stage NEEDS dh_in; a non-first NEEDS dh_out.
371	    if (!S::kIsLast && dh_in == nullptr) return cudaErrorInvalidValue;
372	    if (!S::kIsFirst && dh_out == nullptr) return cudaErrorInvalidValue;
373	    int dev = 0;
374	    cudaError_t err = cudaGetDevice(&dev);
375	    if (err != cudaSuccess) return err;
376	    int n_sms = 0;
377	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
378	    if (err != cudaSuccess) return err;
379	    int occ = 0;
380	    err = cudaOccupancyMaxActiveBlocksPerMultiprocessor(
381	        &occ, (const void*)&pp_decoder_stage_bwd_tc<Stage, NumStages>,
382	        SG_TC_MEGA_BLOCK, 0);
383	    if (err != cudaSuccess) return err;
384	    if (occ < 1) return cudaErrorLaunchOutOfResources;
385	    unsigned launch_ctas = (unsigned)n_sms;
386	    if (ncta_cap > 0 && (unsigned)ncta_cap < launch_ctas) launch_ctas = (unsigned)ncta_cap;
387	    ctx.n_ctas = launch_ctas;
388	    if ((tok.B % 16) != 0) return cudaErrorInvalidValue;
389	    if (ctx.g_arrived) { err = cudaMemsetAsync(ctx.g_arrived, 0, sizeof(unsigned), stream); if (err) return err; }
390	    if (ctx.g_generation) { err = cudaMemsetAsync(ctx.g_generation, 0, sizeof(unsigned), stream); if (err) return err; }
391	    if (ctx.g_next_task) { err = cudaMemsetAsync(ctx.g_next_task, 0, sizeof(int), stream); if (err) return err; }
392	    dim3 grid(launch_ctas), block(SG_TC_MEGA_BLOCK);
393	    pp_decoder_stage_bwd_tc<Stage, NumStages><<<grid, block, 0, stream>>>(
394	        ctx, params, tok, grad, dh_in, dh_out);
395	    return cudaGetLastError();
396	}
