1	// csrc/fused/sm_90/decoder_tc_selftest.cu
2	// ─────────────────────────────────────────────────────────────────────────
3	// Test-only nvcc TU that micro-gates the GEMM engine of
4	// csrc/fused/sm_90/model_stage_decoder_tc.cuh (the decoder TC variant) in the
5	// THREE operand orientations the decoder fwd+bwd use, with the transposed
6	// HBM->smem staging that keeps every wgmma issue on the substrate-validated
7	// TransA=0/TransB=0 path:
8	//
9	//   (fwd) Y[M,Nout] = X[M,Kin] @ W[Nout,Kin]^T   (both K-major; no transpose)
10	//   (dX)  dX[M,Kin] = dY[M,Nout] @ W[Nout,Kin]    (W staged transposed: n=in,k=out)
11	//   (dW)  dW[Nout,Kin] = dY[T,Nout]^T @ X[T,Kin]  (BOTH staged transposed; K=T)
12	//
13	// Driven by tests/hw/test_decoder_tc.py via cpp_extension.load (NOT setup.py —
14	// test-only, never in the shipped glob). It is loaded for sm_90a so the wgmma
15	// PTX is real. Each entry point runs ONE tiny GEMM on a single CTA (256 thr,
16	// 1 producer + 1 consumer warpgroup the engine expects) and returns the fp32
17	// result for comparison against an fp32/fp64 reference of the bf16-rounded
18	// inputs.
19	//
20	// CRITICAL (DESIGN honesty rail + the scalar path's burned-in lesson at
21	// model_stages_decoder.cuh:619-625): the dW gate uses MULTIPLE k-steps with the
22	// transposed staging (K>=128), because a single-tile A=I gate catches a
23	// transpose-LAYOUT bug but NOT a k-step STRIDE bug in the transposed staging —
24	// the exact bug class that made "the forward stay exact while every grad was
25	// garbage" on the scalar path.
26	// ─────────────────────────────────────────────────────────────────────────
27	#include <torch/extension.h>
28	#include <c10/cuda/CUDAStream.h>
29	#include <c10/cuda/CUDAException.h>
30	#include <cuda_runtime.h>
31	#include <cuda_bf16.h>
32	#include <cstdint>
33	
34	#include "csrc/fused/sm_90/model_stage_decoder_tc.cuh"
35	
36	namespace dectc = ::sg::fused::sm90::dectc;
37	namespace wgs   = ::sg::sm90::wgs;
38	
39	// ── smem arena for one A(64x16) + one B(Nmax x16) bf16 tile (the unpipelined
40	//    engine reuses two buffers across k-steps). Nmax = 128. 16B aligned. ──────
41	// Full-shape fwd: M = TILE_M (token rows), N_total = Nout (tiled into N=128/96
42	// atoms by the caller loop), K = Kin. Exercises N-tiling (Nout=512 → 4 tiles).
43	template <int N>
44	__global__ void __launch_bounds__(256)
45	gemm_fwd_kernel(const __nv_bfloat16* __restrict__ X,   // [M, Kin] row-major
46	                const __nv_bfloat16* __restrict__ W,   // [Nout, Kin] row-major
47	                float* __restrict__ D,                 // [M, Nout] row-major out
48	                int Kin, int Nout) {
49	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
50	    extern __shared__ __nv_bfloat16 smem[];
51	    __nv_bfloat16* sA = smem;
52	    // A-ring holds kDecMaxIL A-tiles per slot (the M-atom interleave group width;
53	    // capped, all selftest kernels use MaxAtomsM>=2 so the group is min(2,maxIL)).
54	    __nv_bfloat16* sB = sA + dectc::kDecTcStages * dectc::kDecMaxIL * 64 * 16;   // B ring after the A ring
55	    const int M = dectc::kTileM;
56	    const int m_atoms = M / 64;
57	    const int k_steps = Kin / 16;
58	    // Loop N-tiles of width N over [0, Nout). (fwd) D[m,n] = Σ_k X[m,k]·W[n,k].
59	    for (int n0 = 0; n0 < Nout; n0 += N) {
60	        const int n_real = (Nout - n0) < N ? (Nout - n0) : N;
61	        auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return X[(int64_t)m * Kin + k]; };
62	        auto srcB = [&] (int n, int k) -> __nv_bfloat16 {
63	            int nn = n0 + n; return nn < Nout ? W[(int64_t)nn * Kin + k] : __float2bfloat16(0.f); };
64	        auto out  = [&] (int m, int n, float v) { if (m < M) D[(int64_t)m * Nout + n0 + n] = v; };
65	        dectc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/2>(
66	            0, m_atoms, n_real, k_steps, srcA, srcB, out, sA, sB);
67	    }
68	#else
69	    (void)X; (void)W; (void)D; (void)Kin; (void)Nout;
70	#endif
71	}
72	
73	// (dX) dX[m,kin] = Σ_out dY[m,out]·W[out,kin]. GEMM: A=dY (m, out=K), B=W staged
74	// so n=kin, k=out → srcB(n=kin, k=out) reads W[out, kin] (PHYSICAL TRANSPOSE).
75	// Here N (the wgmma N) = Kin (the in_dim), and the contraction K = Nout.
76	template <int N>
77	__global__ void __launch_bounds__(256)
78	gemm_dx_kernel(const __nv_bfloat16* __restrict__ dY,   // [M, Nout] row-major
79	               const __nv_bfloat16* __restrict__ W,    // [Nout, N] row-major (in_dim=N)
80	               float* __restrict__ dX,                 // [M, N] row-major out
81	               int Nout) {
82	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
83	    extern __shared__ __nv_bfloat16 smem[];
84	    __nv_bfloat16* sA = smem;
85	    __nv_bfloat16* sB = sA + dectc::kDecTcStages * dectc::kDecMaxIL * 64 * 16;   // B ring after the A ring
86	    const int M = dectc::kTileM;
87	    const int m_atoms = M / 64;
88	    const int k_steps = Nout / 16;
89	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 { return dY[(int64_t)m * Nout + k]; };
90	    // B[n=kin, k=out] = W[out, kin]  → transposed read.
91	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 { return W[(int64_t)k * N + n]; };
92	    auto out  = [&] (int m, int n, float v) { if (m < M) dX[(int64_t)m * N + n] = v; };
93	    dectc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/2>(
94	        0, m_atoms, /*n_real=*/N, k_steps, srcA, srcB, out, sA, sB);
95	#else
96	    (void)dY; (void)W; (void)dX; (void)Nout;
97	#endif
98	}
99	
100	// (dW) dW[out,in] = Σ_t dY[t,out]·X[t,in]. GEMM: A=dY staged so m=out, k=t
101	// (dY is [t,out] → srcA(m=out,k=t)=dY[t,out], TRANSPOSE); B=X staged so n=in,
102	// k=t (X is [t,in] → srcB(n=in,k=t)=X[t,in], TRANSPOSE). K = T (the full token
103	// dim → MULTI-k-step, the stride-bug gate). M here is Nout (rows of dW), tiled
104	// as kAtomsM stacked m64 atoms; N is the wgmma N = in_dim.
105	// dW: M = Nout (rows of dW, up to 512 = 8 atoms), N = in_dim (<=128), K = T.
106	template <int N>
107	__global__ void __launch_bounds__(256)
108	gemm_dw_kernel(const __nv_bfloat16* __restrict__ dY,   // [T, Nout] row-major
109	               const __nv_bfloat16* __restrict__ X,    // [T, N] row-major (in_dim=N)
110	               float* __restrict__ dW,                 // [Nout, N] row-major out
111	               int Nout, int T) {
112	#if defined(__CUDA_ARCH__) && (__CUDA_ARCH__ >= 900)
113	    extern __shared__ __nv_bfloat16 smem[];
114	    __nv_bfloat16* sA = smem;
115	    __nv_bfloat16* sB = sA + dectc::kDecTcStages * dectc::kDecMaxIL * 64 * 16;   // B ring after the A ring
116	    const int k_steps = T / 16;
117	    const int m_atoms = (Nout + 63) / 64;        // up to 8 for Nout=512
118	    // A[m=out, k=t] = dY[t, out]  → transposed read.
119	    auto srcA = [&] (int m, int k) -> __nv_bfloat16 {
120	        return m < Nout ? dY[(int64_t)k * Nout + m] : __float2bfloat16(0.f); };
121	    // B[n=in, k=t] = X[t, in]     → transposed read.
122	    auto srcB = [&] (int n, int k) -> __nv_bfloat16 { return X[(int64_t)k * N + n]; };
123	    auto out  = [&] (int m, int n, float v) { if (m < Nout) dW[(int64_t)m * N + n] = v; };
124	    dectc::tc_gemm_block_unpipelined<N, /*MaxAtomsM=*/8>(
125	        0, m_atoms, /*n_real=*/N, k_steps, srcA, srcB, out, sA, sB);
126	#else
127	    (void)dY; (void)X; (void)dW; (void)Nout; (void)T;
128	#endif
129	}
130	
131	// Ring smem: kDecTcStages slots × (kDecMaxIL A-tiles [the M-atom interleave group]
132	// + 1 B-tile). Mirrors DecTcSmem.sA/sB; without the kDecMaxIL factor the
133	// interleaved tc_gemm_block_unpipelined writes the group's 2nd A-tile out of bounds.
134	static size_t arena_bytes() {
135	    return (size_t)(dectc::kDecTcStages * dectc::kDecMaxIL * 64 * 16
136	                    + dectc::kDecTcStages * 128 * 16) * sizeof(__nv_bfloat16) + 256;
137	}
138	
139	template <int N>
140	static torch::Tensor run_fwd(torch::Tensor X, torch::Tensor W, int Kin, int Nout) {
141	    TORCH_CHECK(X.scalar_type() == torch::kBFloat16 && W.scalar_type() == torch::kBFloat16);
142	    TORCH_CHECK(X.is_cuda() && W.is_cuda() && X.is_contiguous() && W.is_contiguous());
143	    auto D = torch::zeros({dectc::kTileM, Nout}, torch::dtype(torch::kFloat32).device(X.device()));
144	    size_t smem = arena_bytes();
145	    auto stream = at::cuda::getCurrentCUDAStream();
146	    cudaFuncSetAttribute(gemm_fwd_kernel<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
147	    gemm_fwd_kernel<N><<<1, 256, smem, stream>>>(
148	        reinterpret_cast<const __nv_bfloat16*>(X.data_ptr()),
149	        reinterpret_cast<const __nv_bfloat16*>(W.data_ptr()), D.data_ptr<float>(), Kin, Nout);
150	    C10_CUDA_CHECK(cudaGetLastError());
151	    return D;
152	}
153	template <int N>
154	static torch::Tensor run_dx(torch::Tensor dY, torch::Tensor W, int Nout) {
155	    auto dX = torch::zeros({dectc::kTileM, N}, torch::dtype(torch::kFloat32).device(dY.device()));
156	    size_t smem = arena_bytes();
157	    auto stream = at::cuda::getCurrentCUDAStream();
158	    cudaFuncSetAttribute(gemm_dx_kernel<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
159	    gemm_dx_kernel<N><<<1, 256, smem, stream>>>(
160	        reinterpret_cast<const __nv_bfloat16*>(dY.data_ptr()),
161	        reinterpret_cast<const __nv_bfloat16*>(W.data_ptr()), dX.data_ptr<float>(), Nout);
162	    C10_CUDA_CHECK(cudaGetLastError());
163	    return dX;
164	}
165	template <int N>
166	static torch::Tensor run_dw(torch::Tensor dY, torch::Tensor X, int Nout, int T) {
167	    auto dW = torch::zeros({Nout, N}, torch::dtype(torch::kFloat32).device(dY.device()));
168	    size_t smem = arena_bytes();
169	    auto stream = at::cuda::getCurrentCUDAStream();
170	    cudaFuncSetAttribute(gemm_dw_kernel<N>, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem);
171	    gemm_dw_kernel<N><<<1, 256, smem, stream>>>(
172	        reinterpret_cast<const __nv_bfloat16*>(dY.data_ptr()),
173	        reinterpret_cast<const __nv_bfloat16*>(X.data_ptr()), dW.data_ptr<float>(), Nout, T);
174	    C10_CUDA_CHECK(cudaGetLastError());
175	    return dW;
176	}
177	
178	// Runtime-N dispatch to the compile-time template (decoder's N set: 128 in/out/
179	// ff0(dX)/ff2(dX); ff0 fwd N=dff=512 tiled as 4x128 by the real header, but the
180	// micro-gate exercises the atom widths the engine issues: 128 (and 96 for head)).
181	static torch::Tensor gemm_fwd(torch::Tensor X, torch::Tensor W, int N, int Kin, int Nout) {
182	    switch (N) { case 96: return run_fwd<96>(X, W, Kin, Nout); case 128: return run_fwd<128>(X, W, Kin, Nout);
183	                 default: TORCH_CHECK(false, "fwd N ", N); }
184	}
185	static torch::Tensor gemm_dx(torch::Tensor dY, torch::Tensor W, int N, int Nout) {
186	    switch (N) { case 96: return run_dx<96>(dY, W, Nout); case 128: return run_dx<128>(dY, W, Nout);
187	                 default: TORCH_CHECK(false, "dx N ", N); }
188	}
189	static torch::Tensor gemm_dw(torch::Tensor dY, torch::Tensor X, int N, int Nout, int T) {
190	    switch (N) { case 96: return run_dw<96>(dY, X, Nout, T); case 128: return run_dw<128>(dY, X, Nout, T);
191	                 default: TORCH_CHECK(false, "dw N ", N); }
192	}
