194	PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
195	    m.def("gemm_fwd", &gemm_fwd, "TC fwd Y=X@W^T (TILE_M x N), bf16/fp32acc");
196	    m.def("gemm_dx",  &gemm_dx,  "TC dX=dY@W (W transposed-staged), bf16/fp32acc");
197	    m.def("gemm_dw",  &gemm_dw,  "TC dW=dY^T@X (both transposed-staged, K=T), bf16/fp32acc");
198	    m.attr("TILE_M") = (int)dectc::kTileM;
199	}
