380	#ifdef SG_VIT_PROFILE
381	// Diagnostic-only: read + reset the per-phase clock64 maxima (cycles). Returns
382	// [P1_fwd, P1_bwd, P2_dW, P3_opt]. Call AFTER one tc_train_step; divide by the
383	// SM clock to convert to ms (or just read the RATIOS — phase attribution).
384	static std::vector<int64_t> tc_profile_read() {
