34	namespace mb = ::sg::fused::sm90::mb;
35	namespace mbtc = ::sg::fused::sm90::mbtc;
36	using ::sg::fused::PersistentContext;
37	using ::sg::fused::sm90::MambaTokenCtx;
38	using ::sg::fused::sm90::FusedOptState;
39	using ::sg::fused::sm90::OptId;
40	using ::sg::fused::sm90::kMambaTotalElems;
