58	// mega_vit_real_adamw_tc — the WIRED ViT TC launcher. Boundary mirrors the scalar
59	// mega_vit_real_adamw EXCEPT it takes NO workspace pointer (TC workspace is a
60	// different size; this TU owns it). `loss_out` points into the caller's
61	// state[3*total] slot.
62	//
63	// OPTID-GENERIC (owner baseline directive — all 33 cells on L3-TC): identical to the
64	// decoder TC launcher — the wgmma fwd+bwd is optimizer-independent, only the per-
65	// element tail (apply_optimizer<Opt>) differs. `opt_id` selects the kernel
66	// instantiation over the SAME [m|v|extra]+loss state buffer (ema = extra slice for
67	// grokfast/grokadamw; the neuralgrok psi-net pack lives at the head of extra). The
68	// STAGED/model-coupled/SG2 optimizers are NOT cases (no single-launch TC path);
69	// dispatch.cpp gates them out and an unsupported id returns cudaErrorInvalidValue.
70	cudaError_t mega_vit_real_adamw_tc(
71	        PersistentContext ctx, float* params,
72	        const float* patches, const int* targets, int B,
73	        float* state, float* grad, float* /*workspace_unused*/, float* loss_out,
74	        float lr, int step, const FusedScalars& scalars, cudaStream_t stream,
75	        int ncta_cap, int opt_id) {
76	    const int64_t total = kVitTotalElems;
77	    const int T = B * vit::kSeq;
78	
79	    int dev = 0;
80	    cudaError_t err = cudaGetDevice(&dev);
81	    if (err != cudaSuccess) return err;
82	    int n_sms = 1;
83	    err = cudaDeviceGetAttribute(&n_sms, cudaDevAttrMultiProcessorCount, dev);
84	    if (err != cudaSuccess) return err;
85	    int nCTA = n_sms;
86	    if (ncta_cap > 0 && ncta_cap < nCTA) nCTA = ncta_cap;
87	
88	    const int64_t need = vit_tc_workspace_floats(T, B, nCTA);
89	    VitTcLauncherScratch& sc = vit_tc_launcher_scratch(dev, need);
90	
91	    ctx.g_next_task  = sc.g_next;
92	    ctx.g_arrived    = sc.g_arrived;
93	    ctx.g_generation = sc.g_generation;
94	    ctx.n_tasks      = kVitNumTensors;
95	
96	    float* const extra_slice = state + 2 * total;
97	    FusedOptState st;
98	    st.exp_avg    = state;
99	    st.exp_avg_sq = state + total;
100	    st.ema        = extra_slice;          // grokfast/grokadamw slow-grad EMA
101	    st.psi_W1     = extra_slice + kPsiW1Off;   // neuralgrok psi-net pack
102	    st.psi_b1     = extra_slice + kPsiB1Off;
103	    st.psi_W2     = extra_slice + kPsiW2Off;
104	    // PRODIGY (STAGED global-d) state bindings — the ViT twin of the decoder TC
105	    // launcher's. The cell extends the state buffer to
106	    //   [m | v | extra/s_track | loss | param_init(total) | r_ema | s_ema | d_lr]
107	    //   = 4*total + 4 (host sizes it in dispatch.fused_train_step). The `extra` slice
108	    // doubles as Prodigy's `s` trajectory accumulator (the apply reads st.s_track,
109	    // not st.ema — they alias here, harmless: Prodigy has no slow-grad EMA). loss_out
110	    // points at state+3*total (dispatch's loss_slot), so param_init = loss_out + 1
111	    // and the 3 persisted estimator scalars [r_ema | s_ema | d_lr] follow it.
112	    st.s_track         = extra_slice;            // Prodigy `s` (per-element accumulator)
113	    st.param_init      = loss_out + 1;           // state + 3*total + 1
114	    st.prodigy_persist = loss_out + 1 + total;   // [r_ema | s_ema | d_lr]
115	    // LookSAM (MODEL-COUPLED SAM 2nd backward) — the ViT twin of the decoder TC
116	    // launcher's sam_dir binding. sam_dir is the PERSISTENT cached SAM direction
117	    // (g_sam − g), carried across steps in the `extra` slice (aliases the grokfast EMA /
118	    // Prodigy s_track slot — harmless: LookSAM has none of those). The in-kernel P2.4
119	    // phase WRITES it on SAM steps (st.looksam_sam!=0); the apply tail READS it every step.
120	    st.sam_dir         = extra_slice;            // [total] cached SAM direction
121	    // SuperGrok11/15 (MODEL-COUPLED SAM 2nd backward + per-tensor meta-net mu). State
122	    // layout: [m | v | mu | loss | sharpness(total) | phi_pack(4H+1)] — the ViT twin of
123	    // the decoder binding. st.mu = the `extra` slice (P2.45-filled, apply reads it);
124	    // st.sharpness = loss_out+1 (PERSISTED (g_sam−g)² from P2.4); st.sg_phi_W1/b1/W2 =
125	    // the host-scattered phi pack after sharpness (sg_phi_b2 read on-device from [H]).
126	    st.mu              = extra_slice;            // [total] meta-net mu (P2.45-filled)
127	    {
128	        float* sharp_base = loss_out + 1;        // state + 3*total + 1
129	        float* phi_base   = sharp_base + total;  // phi pack after sharpness
130	        st.sharpness = sharp_base;
131	        st.sg_phi_W1 = phi_base + kSgPhiW1Off;
132	        st.sg_phi_b1 = phi_base + kSgPhiB1Off;
133	        st.sg_phi_W2 = phi_base + kSgPhiW2Off;   // sg_phi_b2 read on-device from [H]
134	    }
135	    apply_scalars(st, scalars);   // FULL scalar set (+ d0/d_coef/beta3 + rho/looksam_sam/sg_rescale)
136	    st.lr = lr;
137	
138	    ViTInputCtx in;
139	    in.patches   = patches;
140	    in.targets   = targets;
141	    in.B         = B;
142	    in.workspace = sc.workspace;
143	    in.loss_out  = loss_out;
144	
145	    switch (static_cast<OptId>(opt_id)) {
146	        case OptId::AdamW:
147	            return launch_fused_vit_megakernel_tc<OptId::AdamW>(
148	                ctx, params, in, grad, lr, step, st, stream, nCTA);
149	        case OptId::Lion:
150	            return launch_fused_vit_megakernel_tc<OptId::Lion>(
151	                ctx, params, in, grad, lr, step, st, stream, nCTA);
152	        case OptId::Grokfast:
153	            return launch_fused_vit_megakernel_tc<OptId::Grokfast>(
154	                ctx, params, in, grad, lr, step, st, stream, nCTA);
155	        case OptId::GrokAdamW:
156	            return launch_fused_vit_megakernel_tc<OptId::GrokAdamW>(
157	                ctx, params, in, grad, lr, step, st, stream, nCTA);
158	        case OptId::NeuralGrok:
159	            return launch_fused_vit_megakernel_tc<OptId::NeuralGrok>(
160	                ctx, params, in, grad, lr, step, st, stream, nCTA);
161	        case OptId::Prodigy:
162	            // STAGED global-d: the SAME single persistent launch — the d-estimate
163	            // cross-tensor reduction is an IN-KERNEL phase (P2.6, between B2 and P3),
164	            // not a separate launch. st carries param_init/prodigy_persist/d0/d_coef/
165	            // beta3; the kernel decays+accumulates the EMA, updates d, applies.
166	            return launch_fused_vit_megakernel_tc<OptId::Prodigy>(
167	                ctx, params, in, grad, lr, step, st, stream, nCTA);
168	        case OptId::Muon:
169	            // STAGED grid-cooperative Newton-Schulz: the SAME single persistent launch —
170	            // the NS orthogonalization of the 2D weights is an IN-KERNEL phase (P2.7,
171	            // between B2 and P3), looping the matrices with grid barriers. The momentum
172	            // buffer is the PERSISTENT m-slice (st.exp_avg, bound above); st.beta1 is the
173	            // Muon momentum; the 1D/non-2D weights take the AdamW tail in P3 (reading
174	            // st.exp_avg/exp_avg_sq). The per-matrix NS scratch lives in the workspace.
175	            return launch_fused_vit_megakernel_tc<OptId::Muon>(
176	                ctx, params, in, grad, lr, step, st, stream, nCTA);
177	        case OptId::LookSAM:
178	            // MODEL-COUPLED SAM 2nd backward (vit SAM-tier lane): the SAME single
179	            // persistent launch — the perturb→2nd in-kernel fwd+bwd→sam_dir=g_sam−g is
180	            // an IN-KERNEL phase (P2.4, between B2 and P2.5/P3), gated to every-k SAM
181	            // steps by st.looksam_sam. The transient backup + g_sam buffers live in the
182	            // workspace (vit_tc_looksam_floats, carved after the Muon scratch); sam_dir
183	            // persists in the extra slice (st.sam_dir, bound above). The apply tail (P3)
184	            // blends g_adj=(1−α)g+α·sam_dir and runs AdamW. NOT a separate launch. The
185	            // decoder twin (mega_decoder_real_adamw_tc_launcher.cu) proved this routing.
186	            return launch_fused_vit_megakernel_tc<OptId::LookSAM>(
187	                ctx, params, in, grad, lr, step, st, stream, nCTA);
188	        case OptId::SuperGrok11:
189	            // MODEL-COUPLED SAM 2nd backward + per-tensor meta-net mu/gate (wave-3 vit
190	            // lane): the SAME single persistent launch — the SAM 2nd backward (P2.4,
191	            // sharpness=(g_sam−g)²) + per-tensor mu precompute (P2.45) + per-tensor cosine
192	            // gate are in-kernel phases; the apply tail (sg11_sweep_b_step) runs in P3.
193	            // SAM scratch reuses the looksam buffers; sharpness + phi pack ride the
194	            // extended state (bound above). The decoder twin proved this routing.
195	            return launch_fused_vit_megakernel_tc<OptId::SuperGrok11>(
196	                ctx, params, in, grad, lr, step, st, stream, nCTA);
197	        case OptId::SuperGrok15:
198	            // Same SAM 2nd backward + mu precompute; SIMPLER tail (host-scalar gate, no
199	            // cosine stage). sg15_sweep_b_step does the per-coord alpha clip + AdamW.
200	            return launch_fused_vit_megakernel_tc<OptId::SuperGrok15>(
201	                ctx, params, in, grad, lr, step, st, stream, nCTA);
202	        default:
203	            return cudaErrorInvalidValue;
204	    }
