103	// =========================================================================
104	//  §1.3  CU/XCD pinning: read the hardware id register.
105	//
106	//  s_getreg HW_ID exposes the CU (compute unit) and SE (shader engine) the
107	//  wavefront runs on. On CDNA3 the XCD a workgroup landed on is derivable from
108	//  this; the host pins one persistent workgroup per CU so its optimizer-state
109	//  slice stays warm in that CU's L2 slice for the whole step (§1.3, the AMD
110	//  analog of %smid pinning). HW_ID encoding: bits [11:8] = CU_ID, [13] = SE.
111	// =========================================================================
112	__device__ __forceinline__ unsigned cu_id() {
113	#if defined(__AMDGCN__)
114	    // s_getreg_b32 dst, hwreg(HW_REG_HW_ID=4, offset=0, width=32).
115	    // The intrinsic packs (reg<<0)|(offset<<6)|((width-1)<<11); HW_ID=4.
116	    unsigned hwid = __builtin_amdgcn_s_getreg(/*hwreg=*/((4) | (0 << 6) | ((32 - 1) << 11)));
117	    return (hwid >> 8) & 0xfu;   // CU_ID field
118	#else
119	    return 0u;
120	#endif
121	}
