123	// AGENT-scope (device-wide, cross-XCD) atomic add. Mirrors §2.13. Returns the
124	// previous value (fetch-add semantics) so the grid barrier can detect the last
125	// arriver. Under the free-standing amdgcn gate __hip_atomic_fetch_add is macro-
126	// shimmed to __atomic_fetch_add (see scripts/amdgcn_check.sh); under real hipcc
127	// it carries the AGENT memory scope.
128	__device__ __forceinline__ unsigned atomic_add_agent_u32(unsigned* addr,
129	                                                         unsigned v) {
130	    return __hip_atomic_fetch_add(addr, v, __ATOMIC_RELAXED,
131	                                  __HIP_MEMORY_SCOPE_AGENT);
132	}
133	__device__ __forceinline__ int atomic_add_agent_i32(int* addr, int v) {
134	    return __hip_atomic_fetch_add(addr, v, __ATOMIC_RELAXED,
135	                                  __HIP_MEMORY_SCOPE_AGENT);
136	}
137	// AGENT-scope exchange/load. Under real hipcc these carry the AGENT scope; the
138	// free-standing gate shims __hip_atomic_load to a scopeless __atomic_load_n and
139	// has no __hip_atomic_exchange shim, so the exchange routes through the scopeless
140	// __atomic_exchange_n on the gate path (the AGENT-scoped form is the hipcc path).
141	__device__ __forceinline__ unsigned atomic_exch_agent_u32(unsigned* addr,
142	                                                          unsigned v) {
143	#if defined(__HIPCC__) || defined(__HIP_DEVICE_COMPILE__)
144	    return __hip_atomic_exchange(addr, v, __ATOMIC_RELAXED,
145	                                 __HIP_MEMORY_SCOPE_AGENT);
146	#else
147	    return __atomic_exchange_n(addr, v, __ATOMIC_RELAXED);
148	#endif
149	}
150	__device__ __forceinline__ unsigned atomic_load_agent_u32(unsigned* addr) {
151	    return __hip_atomic_load(addr, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
152	}
