154	// =========================================================================
155	//  §1.1 / §1.2  TaskQueue — global work counter + work-stealing.
156	//
157	//  Identical shape to the sm_90 version: one global int the host zero-inits,
158	//  every persistent workgroup pulls indices via atomic_add_agent until the
159	//  counter passes n_tasks. AGENT scope makes the counter coherent across all 8
160	//  XCDs (a CU on XCD 3 and a CU on XCD 7 see one consistent sequence).
161	// =========================================================================
162	struct TaskQueue {
163	    int* g_next_task;
164	    int  n_tasks;
165	
166	    __device__ __forceinline__ TaskQueue(int* counter, int total)
167	        : g_next_task(counter), n_tasks(total) {}
168	
169	    __device__ __forceinline__ int next() {
170	        return atomic_add_agent_i32(g_next_task, 1);
171	    }
172	
173	    // Per-workgroup pull: lane 0 of the workgroup does the single atomic and
174	    // broadcasts via LDS; the whole workgroup then cooperates on that tensor.
175	    __device__ __forceinline__ int next_block(int* lds_slot) {
176	        if (threadIdx.x == 0) {
177	            *lds_slot = atomic_add_agent_i32(g_next_task, 1);
178	        }
179	        __builtin_amdgcn_s_barrier();
180	        int t = *lds_slot;
181	        __builtin_amdgcn_s_barrier();
182	        return t;
183	    }
184	};
