186	// =========================================================================
187	//  §1.4  GridBarrier — hand-built, reusable, sense-reversing grid barrier.
188	//
189	//  Same algorithm as the sm_90 GridBarrier (see that header for the full reuse-
190	//  hazard argument): each workgroup samples the generation, AGENT-releases its
191	//  phase writes, joins the arrival count; the last arriver resets the count and
192	//  advances the generation; everyone else spins on the generation; all then
193	//  AGENT-acquire. CDNA has no DSMEM/grid::sync, so AGENT-scope global atomics +
194	//  fences are the only cross-workgroup mechanism (§2.13).
195	//
196	//  §1.14 fences: one release fence before publish, one acquire fence after the
197	//  generation advances. The intra-workgroup join is s_barrier (no global fence).
198	// =========================================================================
199	struct GridBarrier {
200	    unsigned* g_arrived;
201	    unsigned* g_generation;
202	    unsigned  n_groups;   // number of persistent workgroups (one per CU)
203	
204	    __device__ __forceinline__ GridBarrier(unsigned* arrived,
205	                                            unsigned* generation,
206	                                            unsigned groups)
207	        : g_arrived(arrived), g_generation(generation), n_groups(groups) {}
208	
209	    __device__ __forceinline__ void sync() const {
210	        // Whole workgroup must reach the barrier before lane 0 publishes.
211	        __builtin_amdgcn_s_barrier();
212	
213	        if (threadIdx.x == 0) {
214	            unsigned my_gen = atomic_load_agent_u32(g_generation);
215	
216	            // §1.14 RELEASE: phase writes visible device-wide before arrival.
217	            __builtin_amdgcn_fence(__ATOMIC_RELEASE, "agent");
218	
219	            unsigned prev = atomic_add_agent_u32(g_arrived, 1u);
220	            if (prev + 1u == n_groups) {
221	                // Last arriver: clear count for next phase, then advance gen.
222	                atomic_exch_agent_u32(g_arrived, 0u);
223	                __builtin_amdgcn_fence(__ATOMIC_RELEASE, "agent");
224	                atomic_add_agent_u32(g_generation, 1u);
225	            } else {
226	                while (atomic_load_agent_u32(g_generation) == my_gen) {
